questions.q:
Afficher le nombre d'employés de sexe masculin (M) par service.

A. Select NumServ, Count(*) from Employé where Sexe='M' Group by Matricule, NumServ ;
B. Select NumServ, Matricule, Count(*) from Employé where Sexe='M' Group by Matricule, NumServ ;
C. Select Count(*) from Employé where Sexe='M' Group by NumServ ;
D. Select Count(*) from Employé Group by NumServ, Sexe Having Sexe='M' ;

Afficher les noms des chefs de service.

A. Select Nom from Employé, Service where Employé.NumServ = Service.NumServ ;
B. Select Nom from Employé where 'chef de service' ;
C. Select Nom from Employé, Service where Employé.Matricule = Service.Matricule ;
D. Select Nom from Employé where Matricule IN (Select Matricule from Service) ;

Afficher les noms des services qui ont plus de 10 employés.

A. Select NomServ From Service Where Count(*) > 10 ;
B. Select NomServ From Employé, Service where Employé.NumServ = Service.NumServ Group By Employé.Matricule, Service.NumServ, NomServ Having Count(*) > 10 ;
C. Select NomServ From Employé, Service where Employé.NumService = Service.NumServ Group By Service.NumServ, NomServ Having Count(*) > 10 ;
D. Select NomServ From Employé, Service where Employé.NumServ = Service.NumServ Group By Employé.NumServ, NomServ Having Count(*) > 10 ;

Créer la table Employé : le sexe ne peut prendre que M ou F, les autres tables sont déjà créées.

A. CREATE TABLE Employé (Matricule INT, nom CHAR(15), prénom CHAR(20), Sexe CHAR(1) CHECK(Sexe='M' OR Sexe='F'), NumServ INT, PRIMARY KEY (Matricule, NumServ)) ;
B. CREATE TABLE Employé (Matricule INT PRIMARY KEY, nom CHAR(15), prénom CHAR(20), Sexe CHAR(1) CHECK(Sexe='M' OR Sexe='F'), NumServ INT REFERENCES Service) ;
C. CREATE TABLE Employé (Matricule INT, nom CHAR(15), prénom CHAR(20), Sexe CHAR(1) CHECK(Sexe='M' OR Sexe='F'), NumServ INT REFERENCES Service, PRIMARY KEY(Matricule)) ;
D. CREATE TABLE Employé (Matricule INT PRIMARY KEY, nom CHAR(15), prénom CHAR(20), Sexe CHAR(1) CHECK(Sexe='M' OR Sexe='F'), NumRayon INT, FOREIGN KEY (NumServ) REFERENCES Service) ;

Afficher pour chaque employé son nom et son salaire moyen de l'année 2020.

A. Select Nom, AVG(Montant) from Employé, Salaire where Employé.Matricule = Salaire.Matricule And Année=2020 Group By Employé.Matricule, Nom ;
B. Select Nom, AVG(Montant) from Employé, Salaire where Employé.Matricule = Salaire.Matricule And Année=2020 Group By Nom, Montant ;
C. Select Nom, AVG(Montant) from Employé, Salaire where Employé.Matricule = Salaire.Matricule And Année=2020 Group By Employé.Matricule, Nom, Sum(Montant) ;
D. Select Nom, AVG(Montant) from Employé, Salaire where Employé.Matricule = Salaire.Matricule Group By Employé.Matricule, Nom, Année HAVING Année=2020 ;

Ajouter l'employé de nom Magengo, prénom Guttembert, sexe M, matricule 154, affecté au service 15.

A. Insert Into Employé (nom, prénom, Sexe, Matricule, NumServ) Values ('Magengo','Guttembert','M',154,15) ;
B. Insert Into Employé (Matricule, nom, prénom, Sexe, NumServ) Values ('Magengo','Guttembert','M',154,15) ;
C. Insert Into Employé Values ('Magengo','Guttembert','M',154,15) ;
D. Update Employé Set Matricule=154, nom='Magengo', prénom='Guttembert', Sexe='M', NumServ=15 ;
